BEGIN;
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,email VARCHAR(255) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role VARCHAR(50) NOT NULL DEFAULT 'student',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS classroom_sessions(id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,topic VARCHAR(500) NOT NULL,subject VARCHAR(255),difficulty VARCHAR(50) NOT NULL DEFAULT 'intermediate',status VARCHAR(50) NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS session_messages(id SERIAL PRIMARY KEY,session_id INTEGER REFERENCES classroom_sessions(id) ON DELETE CASCADE,agent_role VARCHAR(100),content TEXT NOT NULL,message_type VARCHAR(50) NOT NULL DEFAULT 'teaching',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS student_progress(id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,topic VARCHAR(500) NOT NULL,mastery_score INTEGER NOT NULL DEFAULT 0,sessions_completed INTEGER NOT NULL DEFAULT 0,last_assessed TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,topic));
CREATE TABLE IF NOT EXISTS quiz_attempts(id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,session_id INTEGER REFERENCES classroom_sessions(id) ON DELETE SET NULL,questions JSONB,answers JSONB,score INTEGER,max_score INTEGER,completed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS password_reset_tokens(id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,token VARCHAR(255) NOT NULL,expires_at TIMESTAMPTZ NOT NULL,used BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS curriculum_modules(id SERIAL PRIMARY KEY,teacher_id INTEGER REFERENCES users(id) ON DELETE CASCADE,title VARCHAR(500) NOT NULL,subject VARCHAR(255),description TEXT,difficulty VARCHAR(50) NOT NULL DEFAULT 'intermediate',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assignments(id SERIAL PRIMARY KEY,teacher_id INTEGER REFERENCES users(id) ON DELETE CASCADE,module_id INTEGER REFERENCES curriculum_modules(id) ON DELETE SET NULL,title VARCHAR(500) NOT NULL,instructions TEXT,due_at TIMESTAMPTZ,max_score INTEGER NOT NULL DEFAULT 100,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assignment_submissions(id SERIAL PRIMARY KEY,assignment_id INTEGER REFERENCES assignments(id) ON DELETE CASCADE,student_id INTEGER REFERENCES users(id) ON DELETE CASCADE,content TEXT,score INTEGER,feedback TEXT,submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(),graded_at TIMESTAMPTZ,UNIQUE(assignment_id,student_id));
CREATE TABLE IF NOT EXISTS grade_reports(id SERIAL PRIMARY KEY,student_id INTEGER REFERENCES users(id) ON DELETE CASCADE,teacher_id INTEGER REFERENCES users(id) ON DELETE SET NULL,period VARCHAR(64),payload JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS parent_links(id SERIAL PRIMARY KEY,parent_email VARCHAR(255) NOT NULL,student_id INTEGER REFERENCES users(id) ON DELETE CASCADE,consent BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(parent_email,student_id));
COMMIT;
